{
  "status": "SUPPORTED",
  "task_summary": "Prepare two refreshment stations on side tables and move the remote to the central coffee table.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_container",
        "entity_kind": "OBJECT",
        "function": "vessel_holding_refreshment",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "mug", "glass"],
        "required_properties": ["holds_consumable"]
      },
      {
        "id": "side_table",
        "entity_kind": "REGION",
        "function": "support_surface_near_chair",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["end_table", "side_table"],
        "required_properties": ["stable_support", "flat_top"]
      },
      {
        "id": "entertainment_device",
        "entity_kind": "OBJECT",
        "function": "user_input_interface",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote_control"],
        "required_properties": ["has_button_interface"]
      },
      {
        "id": "central_access_point",
        "entity_kind": "REGION",
        "function": "common_access_location",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["coffee_table"],
        "required_properties": ["central_position"]
      }
    ],
    "functional_relations": [
      {
        "id": "rel_place_refreshment",
        "subject_role": "refreshment_container",
        "relation": "placed_on",
        "object_role": "side_table",
        "required": true
      },
      {
        "id": "rel_place_remote",
        "subject_role": "entertainment_device",
        "relation": "placed_on",
        "object_role": "central_access_point",
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op_set_refreshment",
        "operation": "transfer_container_to_surface",
        "source_role": "refreshment_container",
        "target_role": "side_table",
        "operation_count": 2,
        "reuse_policy": "DEDICATED_PER_TARGET"
      },
      {
        "id": "op_set_remote",
        "operation": "transfer_device_to_surface",
        "source_role": "entertainment_device",
        "target_role": "central_access_point",
        "operation_count": 1,
        "reuse_policy": "REUSABLE_ACROSS_TARGETS"
      }
    ]
  },
